import { useState, useEffect, useRef } from 'react'
import { IdleView } from './components/IdleView'
import { ProcessingView } from './components/ProcessingView'
import { SuccessView } from './components/SuccessView'
import { ErrorView } from './components/ErrorView'

export type UIState = 'IDLE' | 'PROCESSING' | 'SUCCESS' | 'ERROR'

export interface BulletRewrite {
  original: string
  rewritten: string
  justification: string
}

export interface AnalysisResult {
  keyword_gaps: string[]
  rewritten_bullet_points: BulletRewrite[]
  stack_redundancy_warning: string
  one_page_verdict: string
}

export interface SuccessPayload {
  jobId: string
  matchScore: number
  analysisResults: AnalysisResult
}

const API_BASE = import.meta.env.VITE_API_URL ?? 'http://localhost:3000'
const POLL_INTERVAL_MS = 2000

export default function App() {
  const [uiState, setUiState] = useState<UIState>('IDLE')
  const [jobId, setJobId] = useState<string | null>(null)
  const [successPayload, setSuccessPayload] = useState<SuccessPayload | null>(null)
  const [errorMessage, setErrorMessage] = useState<string | null>(null)
  const [consecutiveRetries, setConsecutiveRetries] = useState<number>(0)

  // Lifted form context — survives IDLE → PROCESSING → ERROR → IDLE transitions
  const [file, setFile] = useState<File | null>(null)
  const [jobDescription, setJobDescription] = useState<string>('')

  const intervalRef = useRef<ReturnType<typeof setInterval> | null>(null)

  const stopPolling = () => {
    if (intervalRef.current) {
      clearInterval(intervalRef.current)
      intervalRef.current = null
    }
  }

  useEffect(() => {
    if (!jobId) return

    intervalRef.current = setInterval(async () => {
      try {
        const res = await fetch(`${API_BASE}/api/v1/analyze/${jobId}`)
        const json = await res.json()

        if (!res.ok) {
          stopPolling()
          setConsecutiveRetries((prev) => prev + 1) // Failure count handled at error transition boundaries
          setErrorMessage(json.message ?? 'Polling request failed.')
          setUiState('ERROR')
          return
        }

        const status: string = json.data.status

        if (status === 'COMPLETED') {
          stopPolling()
          setSuccessPayload({
            jobId: json.data.jobId,
            matchScore: Number(json.data.matchScore),
            analysisResults: json.data.analysisResults as AnalysisResult,
          })
          setConsecutiveRetries(0) // Wipe out historical attempts on full pipeline resolution
          setUiState('SUCCESS')
        } else if (status === 'FAILED') {
          stopPolling()
          setConsecutiveRetries((prev) => prev + 1) // Failure count handled at error transition boundaries
          setErrorMessage(json.data.errorMessage ?? 'Analysis failed.')
          setUiState('ERROR')
        }
        // PENDING and PROCESSING: keep polling
      } catch {
        stopPolling()
        setConsecutiveRetries((prev) => prev + 1) // Failure count handled at error transition boundaries
        setErrorMessage('Network error. Could not reach the server.')
        setUiState('ERROR')
      }
    }, POLL_INTERVAL_MS)

    return () => stopPolling()
  }, [jobId])

  const handleSubmit = async (selectedFile: File, desc: string) => {
    setUiState('PROCESSING')
    setErrorMessage(null)
    setSuccessPayload(null)
    setConsecutiveRetries(0) // Fresh submission from IDLE completely zeroes out the retry state machine

    const formData = new FormData()
    formData.append('cv', selectedFile)
    formData.append('jobDescription', desc)

    try {
      const res = await fetch(`${API_BASE}/api/v1/analyze`, {
        method: 'POST',
        body: formData,
      })
      const json = await res.json()

      if (!res.ok) {
        setConsecutiveRetries((prev) => prev + 1) // Initial failure transition increments count to 1
        setErrorMessage(json.message ?? 'Failed to submit analysis.')
        setUiState('ERROR')
        return
      }

      setJobId(json.data.jobId)
    } catch {
      setConsecutiveRetries((prev) => prev + 1) // Initial network failure transition increments count to 1
      setErrorMessage('Network error. Could not reach the server.')
      setUiState('ERROR')
    }
  }

  // Soft fallback back to IDLE view without destroying user text/file context 
  const handleReset = () => {
    stopPolling()
    setJobId(null)
    setSuccessPayload(null)
    setErrorMessage(null)
    setUiState('IDLE')
  }

  // Clean wipe used exclusively when clicking "Start Over" on SuccessView
  const handleFullClear = () => {
    stopPolling()
    setJobId(null)
    setSuccessPayload(null)
    setErrorMessage(null)
    setConsecutiveRetries(0)
    setFile(null)
    setJobDescription('')
    setUiState('IDLE')
  }

  return (
    <main className="min-h-screen bg-canvas font-mono flex items-center justify-center p-8">
      <div className="w-full max-w-4xl">
        <header className="mb-8">
          <h1 className="text-6xl font-bold tracking-[-0.03em] text-[#1a1a1a] leading-tight font-sans">
            cv_analyzer.
          </h1>
          <p className="text-xs font-mono text-neutral-400 mt-2 tracking-wide">
            ats keyword gap analysis + bullet rewriter by <span className="text-neutral-500">Jeremy</span>
          </p>
        </header>

        <div className="bg-workspace rounded-3xl p-8">
          {uiState === 'IDLE' && (
            <IdleView
              file={file}
              setFile={setFile}
              jobDescription={jobDescription}
              setJobDescription={setJobDescription}
              onSubmit={handleSubmit}
            />
          )}
          {uiState === 'PROCESSING' && <ProcessingView />}
          {uiState === 'SUCCESS' && successPayload && (
            <SuccessView payload={successPayload} onReset={handleFullClear} />
          )}
          {uiState === 'ERROR' && (
            <ErrorView
              message={errorMessage}
              retries={consecutiveRetries}
              onReset={handleReset}
            />
          )}
        </div>
      </div>
    </main>
  )
}

