        <div className="border-2 border-amber-500/30 bg-amber-500/5 rounded-2xl p-5 mb-4 flex flex-col gap-2">
          <p className="text-xs font-mono text-amber-400 tracking-tight uppercase">stack_redundancy_alert</p>
